// ---- The card pickers' remaining-count badges (team_widgets "cards") ----
// The draft's fake of aatf::card_limits (spec/aatf_rules.md "The card
// economy"). Read for each number: the tier's `cards` for the limit, its
// `a_positions` for the A allowance, its `free` groups and the `card_groups`
// they name for covered cards, and the ruleset's free-card specials whose
// `when` is absent or mentions only tiers (tested as the queried tier),
// captain or positions (VTL11's pass skills). Not faked: `choice` effects,
// `cards`/`a_positions`/`free` effects and `when`s on brackets, systems or
// heights (the manlet bonus, the medals' choice), so a badge can read low,
// never high; nor the B-counts-as-A flag for rulesets that lack it.
function cardLimits(p, t, tier) {
  const rs = RULESETS[D.ruleset];
  const freeCards = new Set();
  for (const s of rs.free_specials || []) {
    if (s.tiers && !s.tiers.includes(tier.id)) continue;
    if (s.captain && t.captain !== p.slot - 1) continue;
    if (s.positions && !s.positions.includes(p.positions.registered)) continue;
    freeCards.add(s.card);
  }
  const left = {};
  for (const [g, n] of Object.entries(tier.free || {})) left[g] = n;
  const groupsOf = card =>
    Object.entries(rs.card_groups || {})
      .filter(([, members]) => members.includes(card)).map(([g]) => g)
      .concat(COM_STYLES.includes(card) ? ["com"] : []);
  let paid = 0;
  for (const card of p.skills.concat(p.com_styles)) {
    if (freeCards.has(card)) continue;
    const cover = groupsOf(card).find(g => left[g] > 0);
    if (cover) left[cover] -= 1;
    else paid += 1;
  }
  let a = 0, b = 0;
  for (const r of Object.values(p.positions.playable)) {
    if (r === "A") a += 1; else if (r === "B") b += 1;
  }
  const counted = a + (rs.b_uses_a ? b : 0);
  const limit = tier.cards - Math.max(0, counted - (tier.a_positions || 0));
  return { paid, limit, left: limit - paid };
}
// One badge: the player's own tier under the active ruleset (the tier his
// stats, registered position and height read as, per recognizedTier), the
// error colour when overdrawn. sample wording: the tooltip.
function cardBadges(p, t) {
  // A rules file that does not load: no badge (the quick actions under the
  // list say so, and the error's text would push the header's row apart).
  if (D.rulesBroken) return null;
  const tier = recognizedTier(p, RULESETS[D.ruleset]);
  return h("span", { class: "row", id: "card-badges",
      title: "Cards left under the player's own tier of the active ruleset (paid cards vs its limit)" },
    // "Cards left for Regular: 0 of 3 cards"; a player no tier matches
    // reads "Cards left:" then why.
    weak(tier ? "Cards left for" : "Cards left:"),
    tier ? (() => { const c = cardLimits(p, t, tier);
      return h("span", { class: "badge" + (c.left < 0 ? " over" : ""),
        title: tier.label + ": " + c.paid + " paid of " + c.limit },
        tier.label + ": " + c.left + " of " + c.limit + " cards"); })()
    : weak("No tier matches"));
}

