  let lastTeam = null, lastPid = null;
  const list = h("div", { id: "cmp-rows" });
  for (const r of rows) {
    const [pid, field, o, n] = r;
    const team = Math.floor(pid / 100);
    if (team !== lastTeam) {
      list.append(h("div", { class: "grp" }, "Team " + team
        + (TEAM17[team] ? " " + TEAM17[team] : "")));
      lastTeam = team; lastPid = null;
    }
    if (pid !== lastPid) {
      list.append(playerHead(pid));
      lastPid = pid;
    }
    const d = diffRowDraw(field, o, n);
    const row = h("div", { class: "drow sel", title: "Select this player",
      onclick: () => { jumpToPlayer(team, pid % 100); render(); } },
      h("span", { class: "f" }, d.label),
      h("span", { class: "v" }, d.oldV + " \u2192 " + d.newV));
    list.append(row);
  }
  c.append(list);
  return c;
